package com.niranjankagri.aitesting.tests.ai;

import com.niranjankagri.aitesting.framework.BaseUiTest;
import com.niranjankagri.aitesting.framework.TestCase;
import com.niranjankagri.aitesting.framework.TestUsers;
import org.testng.annotations.Test;

import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;

/** TC-104: a second request that overlaps the first one is refused and changes nothing. */
public class OverlappingRequestTest extends BaseUiTest {

    @Test(groups = "ui")
    @TestCase("TC-104")
    public void overlappingSickLeaveIsRefused() {
        // Arrange: alice already has annual leave from 2 to 6 Nov 2026
        loginAs(TestUsers.EMPLOYEE);
        dashboardPage.submitRequest("ANNUAL", "2026-11-02", "2026-11-06", "");
        assertThat(dashboardPage.formSuccess()).hasText("Request #1 submitted (5 working days)");

        // Act: sick leave from 5 to 9 Nov overlaps the last two days
        dashboardPage.submitRequest("SICK", "2026-11-05", "2026-11-09", "");

        // Assert: refused, still one request, balance unchanged
        assertThat(dashboardPage.formError()).hasText("These dates overlap another request");
        assertThat(dashboardPage.rows()).hasCount(1);
        assertThat(dashboardPage.annualRemaining()).hasText("19");
    }
}
